package com.cpq.currency.service;

import com.cpq.common.exception.BusinessException;
import com.cpq.currency.dto.*;
import com.cpq.currency.entity.*;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.persistence.EntityManager;
import jakarta.transaction.Transactional;
import java.math.BigDecimal; import java.math.RoundingMode; import java.time.LocalDate; import java.time.YearMonth; import java.util.ArrayList; import java.util.Comparator; import java.util.List; import java.util.Locale; import java.util.Set; import java.util.UUID;

@ApplicationScoped
public class ExchangeRateService {
 private static final Set<String> METHODS=Set.of("LATEST","AVG","MAX","MIN","SPECIFIC_DATE","PREVIOUS_MONTH_DAY","MONTH_DAY","PREVIOUS_MONTH_END");
 @jakarta.inject.Inject EntityManager em;
 public List<CurrencyDTO> currencies(){
  List<CurrencyDTO> out=new ArrayList<>();
  for(Currency c: Currency.<Currency>list("order by sortOrder,code")){CurrencyDTO d=CurrencyDTO.from(c);if(!Boolean.TRUE.equals(c.isBase)){Object[] r=(Object[])em.createNativeQuery("select rate,effective_date from currency_exchange_rate where currency_code=:c and status='ACTIVE' order by effective_date desc,updated_at desc,id desc limit 1").setParameter("c",c.code).getResultStream().findFirst().orElse(null);if(r!=null){d.latestRate=new BigDecimal(r[0].toString()).setScale(12,RoundingMode.HALF_UP).toPlainString();d.latestRateDate=r[1].toString();}}out.add(d);}return out;
 }
 private Currency requireCurrency(String code){if(code==null)throw new BusinessException(400,"CURRENCY_NOT_FOUND");Currency c=Currency.findById(code.toUpperCase(Locale.ROOT));if(c==null)throw new BusinessException(404,"CURRENCY_NOT_FOUND");return c;}
 public void validateCurrencyForTemplate(String code){requireCurrency(code);}
 public List<CurrencyRateDTO> rates(String code,LocalDate from,LocalDate to){requireCurrency(code);String q="currencyCode=?1";List<Object> p=new ArrayList<>();p.add(code.toUpperCase(Locale.ROOT));if(from!=null){q+=" and effectiveDate>=?"+(p.size()+1);p.add(from);}if(to!=null){q+=" and effectiveDate<=?"+(p.size()+1);p.add(to);}q+=" order by effectiveDate desc,updatedAt desc";return CurrencyExchangeRate.<CurrencyExchangeRate>list(q,p.toArray()).stream().map(CurrencyRateDTO::from).toList();}
 @Transactional public CurrencyDTO create(CurrencyRequest r){if(r==null||r.code==null||r.name==null)throw new BusinessException(400,"currency code/name required");String code=r.code.trim().toUpperCase(Locale.ROOT);if(!code.matches("[A-Z]{3,10}"))throw new BusinessException(400,"invalid currency code");if(Currency.findById(code)!=null)throw new BusinessException(409,"currency already exists");Currency c=new Currency();c.code=code;c.name=r.name.trim();c.symbol=r.symbol;c.sortOrder=r.sortOrder==null?0:r.sortOrder;c.enabled=true;c.isBase="CNY".equals(code);c.persist();return CurrencyDTO.from(c);}
 @Transactional public CurrencyDTO update(String code,CurrencyRequest r){Currency c=requireCurrency(code);if("CNY".equals(c.code)&&(Boolean.FALSE.equals(r.enabled)))throw new BusinessException(400,"CNY cannot be disabled");if(r.name!=null)c.name=r.name;if(r.symbol!=null)c.symbol=r.symbol;if(r.sortOrder!=null)c.sortOrder=r.sortOrder;if(r.enabled!=null)c.enabled=r.enabled;return CurrencyDTO.from(c);}
 @Transactional public void delete(String code){Currency c=requireCurrency(code);if(Boolean.TRUE.equals(c.isBase))throw new BusinessException(409,"CURRENCY_IN_USE");Number n=(Number)em.createNativeQuery("select (select count(*) from customer where default_currency=:c)+(select count(*) from quotation where currency=:c)+(select count(*) from currency_exchange_rate where currency_code=:c)").setParameter("c",c.code).getSingleResult();if(n.longValue()>0)throw new BusinessException(409,"CURRENCY_IN_USE");c.delete();}
 @Transactional public CurrencyRateDTO addRate(String code,RateRequest r,UUID uid){Currency c=requireCurrency(code);if(!Boolean.TRUE.equals(c.enabled))throw new BusinessException(409,"CURRENCY_DISABLED");if(r==null||r.rate==null||r.rate.signum()<=0)throw new BusinessException(400,"INVALID_EXCHANGE_RATE");if(r.effectiveDate==null)throw new BusinessException(400,"effectiveDate required");CurrencyExchangeRate x=new CurrencyExchangeRate();x.currencyCode=c.code;x.rate=r.rate.setScale(12,RoundingMode.HALF_UP);x.effectiveDate=r.effectiveDate;x.source=r.source;x.createdBy=uid;x.persist();return CurrencyRateDTO.from(x);}
 @Transactional public CurrencyRateDTO updateRate(String code,UUID id,RateRequest r,UUID uid){Currency c=requireCurrency(code);if(!Boolean.TRUE.equals(c.enabled))throw new BusinessException(409,"CURRENCY_DISABLED");if(id==null||r==null||r.rate==null||r.rate.signum()<=0||r.effectiveDate==null)throw new BusinessException(400,"INVALID_EXCHANGE_RATE");CurrencyExchangeRate x=CurrencyExchangeRate.findById(id);if(x==null||!c.code.equalsIgnoreCase(x.currencyCode))throw new BusinessException(404,"EXCHANGE_RATE_NOT_FOUND");x.rate=r.rate.setScale(12,RoundingMode.HALF_UP);x.effectiveDate=r.effectiveDate;x.source=r.source;return CurrencyRateDTO.from(x);}
 @Transactional public int importRates(String code,List<RateRequest> rows,UUID uid){if(rows==null||rows.isEmpty())throw new BusinessException(400,"导入文件为空");Currency c=requireCurrency(code);if(!Boolean.TRUE.equals(c.enabled))throw new BusinessException(409,"CURRENCY_DISABLED");for(RateRequest r:rows){if(r==null||r.rate==null||r.rate.signum()<=0||r.effectiveDate==null)throw new BusinessException(400,"INVALID_EXCHANGE_RATE");}for(RateRequest r:rows){CurrencyExchangeRate x=new CurrencyExchangeRate();x.currencyCode=c.code;x.rate=r.rate.setScale(12,RoundingMode.HALF_UP);x.effectiveDate=r.effectiveDate;x.source=r.source;x.createdBy=uid;x.persist();}return rows.size();}
 public List<CurrencyRateDTO> matrixRates(String code,LocalDate from,LocalDate to){return rates(code,from,to).stream().collect(java.util.stream.Collectors.toMap(x->x.effectiveDate,x->x,(a,b)->a,java.util.LinkedHashMap::new)).values().stream().toList();}
 public BigDecimal resolve(String code,LocalDate baseDate,CustomerExchangeRateStrategy s){Currency c=requireCurrency(code);if("CNY".equals(c.code))return BigDecimal.ONE.setScale(12);if(baseDate==null)baseDate=LocalDate.now();if(s==null)return latest(code,baseDate);validate(s);if(s.method.equals("LATEST"))return latest(code,baseDate);if(s.method.startsWith("SPECIFIC")||s.method.startsWith("PREVIOUS")||s.method.equals("MONTH_DAY")){LocalDate d=targetDate(s,baseDate);BigDecimal v=daily(code,d);if(v==null)throw new BusinessException(409,"QUOTATION_RATE_NOT_FOUND");return v.setScale(12,RoundingMode.HALF_UP);}int n=s.windowNum==null?1:s.windowNum;LocalDate from=windowFrom(baseDate,n,s.windowUnit);List<BigDecimal> vals=dailyValues(code,from,baseDate);if(vals.isEmpty())throw new BusinessException(409,"QUOTATION_RATE_NOT_FOUND");BigDecimal v=s.method.equals("AVG")?vals.stream().reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(vals.size()),12,RoundingMode.HALF_UP):s.method.equals("MAX")?vals.stream().max(Comparator.naturalOrder()).orElseThrow():vals.stream().min(Comparator.naturalOrder()).orElseThrow();return v.setScale(12,RoundingMode.HALF_UP);}
 private void validate(CustomerExchangeRateStrategy s){if(!METHODS.contains(s.method))throw new BusinessException(400,"EXCHANGE_RATE_STRATEGY_INVALID");if(Set.of("AVG","MAX","MIN").contains(s.method)&&(s.windowNum==null||s.windowNum<1||s.windowUnit==null))throw new BusinessException(400,"EXCHANGE_RATE_STRATEGY_INVALID");if(Set.of("PREVIOUS_MONTH_DAY","MONTH_DAY").contains(s.method)&&(s.dayOfMonth==null||s.dayOfMonth<1||s.dayOfMonth>31))throw new BusinessException(400,"EXCHANGE_RATE_STRATEGY_INVALID");if("SPECIFIC_DATE".equals(s.method)&&(s.specificDate==null||s.specificDate.isAfter(LocalDate.now())))throw new BusinessException(400,"EXCHANGE_RATE_STRATEGY_INVALID");}
 private LocalDate targetDate(CustomerExchangeRateStrategy s,LocalDate base){if("SPECIFIC_DATE".equals(s.method))return s.specificDate;if("PREVIOUS_MONTH_END".equals(s.method))return base.withDayOfMonth(1).minusDays(1);int day=s.dayOfMonth;YearMonth ym=YearMonth.from(base);if("PREVIOUS_MONTH_DAY".equals(s.method)||day>base.getDayOfMonth())ym=ym.minusMonths(1);while(day>ym.lengthOfMonth())ym=ym.minusMonths(1);return ym.atDay(day);}
 private LocalDate windowFrom(LocalDate d,int n,String unit){return switch(unit==null?"DAY":unit){case "WEEK"->d.minusWeeks(n);case "MONTH"->d.minusMonths(n);case "YEAR"->d.minusYears(n);default->d.minusDays(n);};}
 private BigDecimal latest(String code,LocalDate d){List<BigDecimal> v=dailyValues(code,LocalDate.of(1900,1,1),d);if(v.isEmpty())throw new BusinessException(409,"QUOTATION_RATE_NOT_FOUND");return v.get(0).setScale(12,RoundingMode.HALF_UP);}
 public LocalDate effectiveDate(String code,LocalDate baseDate,CustomerExchangeRateStrategy s){if("CNY".equalsIgnoreCase(code))return baseDate;if(s!=null&&(s.method.startsWith("SPECIFIC")||s.method.startsWith("PREVIOUS")||s.method.equals("MONTH_DAY")))return targetDate(s,baseDate);Object v=em.createNativeQuery("select effective_date from currency_exchange_rate where currency_code=:c and status='ACTIVE' and effective_date<=:d order by effective_date desc,updated_at desc,id desc limit 1").setParameter("c",code.toUpperCase(Locale.ROOT)).setParameter("d",baseDate).getResultStream().findFirst().orElse(null);if(v==null)throw new BusinessException(409,"QUOTATION_RATE_NOT_FOUND");return v instanceof LocalDate?(LocalDate)v:LocalDate.parse(v.toString());}
 private BigDecimal daily(String code,LocalDate d){List<BigDecimal> v=dailyValues(code,d,d);return v.isEmpty()?null:v.get(0);}
 @SuppressWarnings("unchecked") private List<BigDecimal> dailyValues(String code,LocalDate from,LocalDate to){List<?> rows=em.createNativeQuery("select distinct on (effective_date) rate from currency_exchange_rate where currency_code=:c and status='ACTIVE' and effective_date between :f and :t order by effective_date desc,updated_at desc,id desc").setParameter("c",code.toUpperCase(Locale.ROOT)).setParameter("f",from).setParameter("t",to).getResultList();List<BigDecimal> out=new ArrayList<>();for(Object x:rows)out.add(new BigDecimal(x.toString()));return out;}
 public CustomerExchangeRateStrategy strategy(UUID customerId){return CustomerExchangeRateStrategy.findById(customerId);}
 @Transactional public CustomerExchangeRateStrategy saveStrategy(UUID customerId,ExchangeRateStrategyRequest r,UUID uid){if(r==null)throw new BusinessException(400,"EXCHANGE_RATE_STRATEGY_INVALID");CustomerExchangeRateStrategy s=CustomerExchangeRateStrategy.findById(customerId);if(s==null){s=new CustomerExchangeRateStrategy();s.customerId=customerId;}else{em.createNativeQuery("insert into customer_exchange_rate_strategy_history(customer_id,method,window_num,window_unit,specific_date,day_of_month,version,changed_by) values (:c,:m,:n,:u,:d,:dom,:v,:uid)").setParameter("c",customerId).setParameter("m",s.method).setParameter("n",s.windowNum).setParameter("u",s.windowUnit).setParameter("d",s.specificDate).setParameter("dom",s.dayOfMonth).setParameter("v",s.version).setParameter("uid",uid).executeUpdate();}s.method=r.method;s.windowNum=r.windowNum;s.windowUnit=r.windowUnit;s.specificDate=r.specificDate;s.dayOfMonth=r.dayOfMonth;s.updatedBy=uid;validate(s);s.version=s.version==null?1:s.version+1;s.persist();return s;}
}
